const AN_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${AN_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const AN_L=(x1,y1,x2,y2,col=AN_G,w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const AN_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}${o.fo?` fill-opacity="${o.fo}"`:''}/>`;
const AN_ar=(x1,y1,x2,y2,col='#18213A',w=4,dash='')=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return AN_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w,dash?`stroke-dasharray="${dash}"`:'')+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const AN_badge=(x,y,n,col,op=1,r=17)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${col||INK}" fill-opacity="${op}"/>`+AN_T(x,y+8,n,{fs:22,fw:800,a:'middle',fill:'#FFFFFF'});
const AN_X=(x,y,s,col)=>AN_L(x-s,y-s,x+s,y+s,col,7)+AN_L(x-s,y+s,x+s,y-s,col,7);
/* a dish opening to the right: vertex (vx,cy), rim radius r px, focal length f px */
const AN_dish=(vx,cy,r,f,col,w=5)=>{let p=[];for(let i=-30;i<=30;i++){const y=r*i/30;p.push(`${(vx+y*y/(4*f)).toFixed(1)},${(cy+y).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`};
/* a ray from the focus to the dish at height y (offset from axis), then parallel to xe */
const AN_ray=(vx,cy,f,y,xe,col,w=2.5)=>{const xd=vx+y*y/(4*f);return AN_L(vx+f,cy,xd,cy+y,col,w)+AN_ar(xd,cy+y,xe,cy+y,col,w)};
/* a feed pattern lobe at (fx,cy) pointing left: r = R cos^n */
const AN_lobe=(fx,cy,R,n,col,fo=.25)=>{let p=[];for(let i=-45;i<=45;i++){const t=i*Math.PI/90,r=R*Math.pow(Math.cos(t),n);p.push(`${(fx-r*Math.cos(t)).toFixed(1)},${(cy+r*Math.sin(t)).toFixed(1)}`)}return `<polygon points="${p.join(' ')}" fill="${col}" fill-opacity="${fo}" stroke="${col}" stroke-width="2.5"/>`};
/* a Yagi seen from above: boom at y, rods at xs with lengths ls; driven index di */
const AN_dishSeg=(vx,cy,y0,y1,f,col,w=5,ex='')=>{let p=[];for(let i=0;i<=12;i++){const y=y0+(y1-y0)*i/12;p.push(`${(vx+y*y/(4*f)).toFixed(1)},${(cy+y).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`};
const AN_yagi=(xs,ls,y,di,col,dcol,w=5)=>AN_L(xs[0]-14,y,xs[xs.length-1]+14,y,AN_G,4)+xs.map((x,i)=>i===di?AN_L(x,y-ls[i]/2,x,y-5,dcol,w)+AN_L(x,y+5,x,y+ls[i]/2,dcol,w)+`<circle cx="${x}" cy="${y}" r="5" fill="${dcol}"/>`:AN_L(x,y-ls[i]/2,x,y+ls[i]/2,col,w)).join('');
/* horn side view: guide from x0 (height gh) to x1, flare to the mouth at x2 (height mh), centred on cy */
const AN_horn=(x0,x1,x2,cy,gh,mh,col)=>`<polygon points="${x0},${cy-gh/2} ${x1},${cy-gh/2} ${x2},${cy-mh/2} ${x2},${cy+mh/2} ${x1},${cy+gh/2} ${x0},${cy+gh/2}" fill="#EEF2FF" stroke="${col}" stroke-width="4" stroke-linejoin="round"/>`;

