function EXTRA(R,ICON){
 /* hook: a rooftop Yagi aimed at a TV tower, and a rooftop dish aimed at a satellite */
 ICON.anYagiRoof=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${AN_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  <polygon points="20,160 90,110 160,160" fill="#E9ECEF" stroke="${AN_G}" stroke-width="3"/>${AN_L(90,110,90,60,AN_G,4)}
  ${AN_yagi([50,80,110,140,170],[56,52,48,46,44],60,1,BLU,ORG,4)}
  ${AN_ar(190,60,270,60,GRN,4)}
  ${AN_L(330,160,330,40,AN_G,4)}${AN_L(310,160,330,40,AN_G,3)}${AN_L(350,160,330,40,AN_G,3)}<circle cx="330" cy="40" r="7" fill="${RED}"/>
  ${AN_T(330,26,'TV tower',{fs:20,fw:800,a:'middle',fill:AN_G})}</g>`;
 ICON.anDishRoof=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${AN_box(0,0,380,170,{fill:'#FFFFFF',st:GRN,sw:3,r:18})}
  <polygon points="20,160 90,110 160,160" fill="#E9ECEF" stroke="${AN_G}" stroke-width="3"/>${AN_L(90,110,68,96,AN_G,4)}
  <g transform="rotate(-30 90 80)">${AN_dish(60,80,40,30,BLU,5)}${AN_L(60,80,90,80,AN_G,2)}<circle cx="90" cy="80" r="5" fill="${GRN}"/></g>
  ${AN_ar(130,60,260,-15+60,GRN,4)}
  <rect x="290" y="16" width="34" height="22" fill="${ORG}"/><rect x="258" y="22" width="28" height="10" fill="${BLU}"/><rect x="328" y="22" width="28" height="10" fill="${BLU}"/>
  ${AN_T(306,66,'satellite',{fs:20,fw:800,a:'middle',fill:AN_G})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.anRecapYagi=(x,y)=>{const N=7,L=[],X=[40];for(let i=0;i<N;i++)L.push(130*Math.pow(.9,i));for(let i=1;i<N;i++)X.push(X[i-1]+2*.15*L[i-1]);
  return `<g transform="translate(${x-210} ${y-165})">${AN_yagi([40,100,150,200,250],[120,112,106,102,98],80,1,BLU,ORG,5)}${AN_ar(280,80,400,80,GRN,6)}
  ${X.map((xx,i)=>AN_L(xx,240-L[i]/2,xx,240+L[i]/2,BLU,5)).join('')}${AN_L(X[0],240,X[N-1],240,AN_G,3)}<circle cx="${X[N-1]+14}" cy="240" r="8" fill="${ORG}"/>${AN_ar(X[N-1]+34,240,400,240,GRN,6)}</g>`};
 ICON.anRecapHorn=(x,y)=>{let p=[];for(let i=-20;i<=20;i++){const t=i/20*0.6;p.push(`${(110+230*Math.cos(t)).toFixed(1)},${(165+230*Math.sin(t)).toFixed(1)}`)}
  return `<g transform="translate(${x-210} ${y-165})">${AN_horn(20,110,330,165,60,270,BLU)}<polyline points="${p.join(' ')}" fill="none" stroke="${ORG}" stroke-width="5"/>${AN_ar(340,165,410,165,GRN,7)}</g>`};
 ICON.anRecapDish=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${AN_dish(40,165,150,110,BLU,7)}${[-120,-60,60,120].map(yy=>AN_ray(40,165,110,yy,400,ORG,3)).join('')}<circle cx="150" cy="165" r="9" fill="${GRN}"/>${AN_L(40,165,410,165,AN_LG,2,'stroke-dasharray="4 5"')}</g>`;
}
